class Solution:
    def sumOfMultiples(self, n: int) -> int:
        return sum(x for x in range(1, n + 1) if x % 3 == 0 or x % 5 == 0 or x % 7 == 0)

class Solution {
public:
    int sumOfMultiples(int n) {
        int total = 0;
        for (int x = 1; x <= n; x++) {
            if (x % 3 == 0 || x % 5 == 0 || x % 7 == 0) {
                total += x;
            }
        }
        return total;
    }
};

